// test/payments/refund.test.js
const { refundPayment } = require('../../src/payments/refund');

function makeFakeProvider(overrides = {}) {
  const calls = [];
  const provider = {
    calls,
    refunds: {
      create: async (args) => {
        calls.push({ method: 'refunds.create', args });
        if (overrides.createError) throw overrides.createError;
        return { id: 're_test_1', status: 'succeeded', amount: args.amount };
      },
    },
    charges: {
      retrieve: async (id) => {
        calls.push({ method: 'charges.retrieve', args: id });
        if (overrides.notFound || id !== 'ch_test_1') {
          const err = new Error('No such charge');
          err.code = 'resource_missing';
          throw err;
        }
        return { id, amount: 5000, amount_refunded: 0 };
      },
    },
  };
  return provider;
}

describe('refundPayment', () => {
  test('refunds the full amount of a known charge', async () => {
    const provider = makeFakeProvider();
    const result = await refundPayment({ provider, chargeId: 'ch_test_1' });
    expect(result.status).toBe('succeeded');
    expect(provider.calls.at(-1).args).toMatchObject({ charge: 'ch_test_1' });
  });

  test('refunds a partial amount when given one', async () => {
    const provider = makeFakeProvider();
    await refundPayment({ provider, chargeId: 'ch_test_1', amount: 1200 });
    expect(provider.calls.at(-1).args.amount).toBe(1200);
  });

  test('rejects an unknown charge without issuing a refund', async () => {
    const provider = makeFakeProvider();
    await expect(
      refundPayment({ provider, chargeId: 'ch_missing' })
    ).rejects.toThrow();
    expect(provider.calls.some((c) => c.method === 'refunds.create')).toBe(false);
  });

