const { dueDate } = require('./due');

// Adds calendar days in local time, so it stays correct across DST changes.
function addCalendarDays(date, days) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

describe('dueDate', () => {
  test('is 30 days after the issue date', () => {
    const issueDate = new Date(2024, 0, 15, 9, 30); // 15 Jan 2024, 09:30 local
    expect(dueDate(issueDate)).toEqual(addCalendarDays(issueDate, 30));
  });

