    const issueDate = new Date(2024, 0, 31, 23, 59, 59); // 31 Jan 2024, 23:59:59 local
    expect(dueDate(issueDate)).toEqual(addCalendarDays(issueDate, 30));
  });

  test('crosses a month boundary correctly', () => {
    const issueDate = new Date(2024, 0, 20, 12, 0); // 20 Jan 2024, noon local
    expect(dueDate(issueDate)).toEqual(new Date(2024, 1, 19, 12, 0)); // 19 Feb 2024, noon local
  });
});
