// test/fakes/paymentProvider.js
export function makeFakeProvider({ failWith = null, alreadyRefunded = false } = {}) {
  const calls = [];
  return {
    calls,
    async refund({ paymentId, amount }) {
      calls.push({ paymentId, amount });
      if (failWith) throw failWith;
      if (alreadyRefunded) {
        const e = new Error('already_refunded'); e.code = 'already_refunded'; throw e;
      }
      return { id: `re_fake_${calls.length}`, paymentId, amount, status: 'succeeded' };
    },
  };
}

