The flakiness comes from calling `new Date()` twice. Near midnight the two calls can land on different sides of the day boundary, so the expected and actual values differ. The test also uses the same `addDays` helper to compute its expected value, so it can't catch a mistake in the rule itself. `dueDate` already takes the issue date as an argument, so the fix is to pass fixed dates and write the expected results out by hand.

```js
// src/billing/due.test.js
import { dueDate } from './due';

// Compare calendar dates (local time), so the assertion is about "which day"
// and not about milliseconds.
const ymd = (d) => [d.getFullYear(), d.getMonth() + 1, d.getDate()];

describe('dueDate', () => {
  test('is 30 days after the issue date', () => {
    const issued = new Date(2024, 0, 15); // 15 Jan 2024
    expect(ymd(dueDate(issued))).toEqual([2024, 2, 14]);
  });

  test('rolls over a month boundary', () => {
    const issued = new Date(2024, 3, 10); // 10 Apr 2024
    expect(ymd(dueDate(issued))).toEqual([2024, 5, 10]);
  });

  test('rolls over a year boundary', () => {
    const issued = new Date(2024, 11, 15); // 15 Dec 2024
    expect(ymd(dueDate(issued))).toEqual([2025, 1, 14]);
  });

  test('accounts for a leap day', () => {
    const issued = new Date(2024, 1, 1); // 1 Feb 2024 (leap year)
    expect(ymd(dueDate(issued))).toEqual([2024, 3, 2]);
  });

  test('does not shift the day when issued just before midnight', () => {
    const issued = new Date(2024, 0, 15, 23, 59, 59);
    expect(ymd(dueDate(issued))).toEqual([2024, 2, 14]);
  });

  test('does not shift the day when issued just after midnight', () => {
    const issued = new Date(2024, 0, 15, 0, 0, 1);
    expect(ymd(dueDate(issued))).toEqual([2024, 2, 14]);
  });

  test('does not mutate the issue date', () => {
    const issued = new Date(2024, 0, 15);
    const before = issued.getTime();
    dueDate(issued);
    expect(issued.getTime()).toBe(before);
  });
});
```

