```js
// In-memory stand-in for the payment provider. Makes no network calls.
// Response shapes are ASSUMED from the provider docs and refund.js usage,
// and have not been checked against the live service.
function createFakeProvider({ failWith = null } = {}) {
  const calls = [];
  const charges = new Map([["ch_test_1", { id: "ch_test_1", amount: 5000, refunded: 0 }]]);
  return {
    calls,
    async refund({ chargeId, amount, idempotencyKey }) {
      calls.push({ chargeId, amount, idempotencyKey });
      if (failWith) throw failWith;
      const c = charges.get(chargeId);
      if (!c) { const e = new Error("No such charge"); e.code = "resource_missing"; throw e; }
      if (c.refunded + amount > c.amount) { const e = new Error("Refund exceeds charge"); e.code = "amount_too_large"; throw e; }
      c.refunded += amount;
      return { id: "re_test_" + calls.length, chargeId, amount, status: "succeeded" };
    },
  };
}
module.exports = { createFakeProvider };
```

