**Fake provider (sketch)**

```js
// test/fakes/fakePaymentProvider.js
function createFakeProvider() {
  const calls = [];
  let nextResponse = { status: 'succeeded' };
  return {
    calls,
    willReturn(r) { nextResponse = r; },
    willThrow(err) { nextResponse = { throw: err }; },
    async refund(req) {
      calls.push(req);
      if (nextResponse.throw) throw nextResponse.throw;
      return { id: 're_fake_1', paymentId: req.paymentId, amount: req.amount, ...nextResponse };
    },
  };
}
module.exports = { createFakeProvider };
```

