import { dueDate } from './due';

describe('dueDate', () => {
  // Local-time constructors, noon by default, so the result doesn't depend
  // on the machine's clock or on which day the test happens to run.
  const d = (y, m, day, h = 12, min = 0, s = 0) =>
    new Date(y, m - 1, day, h, min, s);

  test('is 30 days after the issue date', () => {
    expect(dueDate(d(2024, 1, 15))).toEqual(d(2024, 2, 14));
  });

  test('rolls over a month end', () => {
    expect(dueDate(d(2024, 4, 20))).toEqual(d(2024, 5, 20));
  });

  test('rolls over a year end', () => {
    expect(dueDate(d(2023, 12, 15))).toEqual(d(2024, 1, 14));
  });

  test('handles a leap year (Feb has 29 days in 2024)', () => {
    expect(dueDate(d(2024, 1, 31))).toEqual(d(2024, 3, 1));
  });

  test('handles a non-leap year (Feb has 28 days in 2023)', () => {
    expect(dueDate(d(2023, 1, 31))).toEqual(d(2023, 3, 2));
  });

  test('keeps the time of day when issued just before midnight', () => {
    expect(dueDate(d(2023, 12, 31, 23, 59, 59)))
      .toEqual(d(2024, 1, 30, 23, 59, 59));
  });

  test('does not modify the issue date passed in', () => {
    const issued = d(2024, 1, 15);
    const before = issued.getTime();
    dueDate(issued);
    expect(issued.getTime()).toBe(before);
  });
});
```

